from pathlib import Path
import json,re,hashlib
p=Path(__file__).resolve().parent
read=lambda n:(p/n).read_text(encoding='utf-8-sig')
a=json.loads(read('analog_summary.json'));d=read('digital_tests.log')
r={'scope':'Functional regression of unchanged source/netlists. Not extracted GDS performance signoff.','digital_summary':re.findall(r'== summary: (\d+) passed, (\d+) failed ==',d),'digital_test_lines':re.findall(r'^PASS.*$',d,re.M),'analog_execution_results':a['execution_results'],'quantizer':a['quantizer_delay'],'adc_clock_minimum_margin_ns':a['adc_clock_minimum_margin_ns'],'threshold_interpretation':{'adc_clock':'Measured minimum 0.16 ns > zero sequencing boundary; no specified guardband/assert in bench. Positive measurement is not PVT/PEX timing signoff.','afe':'Measured minimum abs(VDS)-abs(VDSAT)=0.07 V at ff/-20C. No specified minimum guardband/assert; only operating-point measurement.','quantizer':'8/8 correct decisions at each of typical/ss/ff when sampled +61 ns. 23/24 transition delays measured, max 1.58 ns; typical +10mV starts at correct state and has no transition, so no delay obtained for that case.','bias_reference_testmux':'Numerical characterization; no product-level accuracy tolerances/asserts were supplied.'},'reference_difference_v':[0.4929,0.4918,0.4940],'testmux_worst_voltage_error_mv':{'typical':1.962,'ss':2.960,'ff':1.336},'afe_noise_estimate_nvrms':[4.59,5.37,4.06],'afe_noise_limit':'Frozen/chopped schematic estimate with supplied linear MOSCAP approximation, not complete chip noise/ENOB.','dac':'Not rerun. Prior typical even-charge test took roughly 50 minutes; earlier other cases timed out. No new claim of DAC corner or full-loop accuracy.','unverified':['full-chip PEX','supply variation','mismatch/Monte Carlo','end-to-end ADC ENOB/noise','pad parasitics and package','EM/IR'],'initial_runtime_error':'Icarus vvp missing libvvp.so.1 before simulation; preserved under initial_runtime_error, fixed process-local LD_LIBRARY_PATH and reran.','input_hashes':'input_hashes.json'}
h=json.loads(read('input_hashes.json'));r['source_inputs_unchanged_after_simulation']=all(hashlib.sha256((p/f).read_bytes()).hexdigest()==v for f,v in h.items())
(p/'functional_summary.json').write_text(json.dumps(r,indent=2),encoding='utf-8')
print(json.dumps({k:v for k,v in r.items() if k not in ['digital_test_lines','analog_execution_results']},indent=2))
